<?php use App\Core\Security; use App\Services\ServerRankingService; use App\Services\WeaponRankingService; ?>
<section class="panel"><h2>Spielerranglisten · <?=Security::e($server['name'])?></h2><p>Bis zu 100 Spieler je Wertung. Gleichstände erhalten denselben Platz. Bottraining wird separat ausgewertet.</p><a class="btn btn-secondary" href="/players">Spielerverwaltung</a></section>
<?php require __DIR__.'/weapon_ranking.php'; ?>
<?php if($statistics['state']!=='ready'):?><section class="panel"><p><?=Security::e($statistics['message'])?></p></section><?php else:$d=$statistics['data'];$c=$d['collection'];?>
<section class="panel"><p>Statistikstand <?=Security::e($d['generatedAt'])?>. Für die PvP-Gesamtwertung: mindestens <?=$c['MinShots']?> Schüsse und <?=$c['MinKills']?> Kills; Bottraining: <?=$c['MinBotShots']?> Schüsse und <?=$c['MinBotKills']?> Kills.</p>
<p>Bestehende PvP-Erfassungsregeln: Warmup <?=$c['CountPvpWarmup']?'enthalten':'ausgeschlossen'?>, Teamkills <?=$c['CountTeamKills']?'enthalten':'ausgeschlossen'?>. Die Wertung folgt diesen bestehenden Regeln. Kills mit übernommener Waffe zählen nur gegen menschliche Gegner außerhalb des Warmups.</p></section>
<?php foreach(ServerRankingService::LABELS as $metric=>$label):?><section class="panel"><details <?=$metric==='rating'?'open':''?>><summary><strong><?=Security::e($label)?></strong></summary>
<?php if(!$d['boards'][$metric]):?><p>Noch keine qualifizierten Einträge oder Erfassung ausgeschaltet.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Platz</th><th>Spieler</th><th>Wert</th></tr></thead><tbody><?php foreach($d['boards'][$metric] as $r):?><tr><td><?=$r['rank']?></td><td><?=Security::e($r['name'])?> <small><?=Security::e($r['steamId'])?></small></td><td><?=number_format($r['value'],in_array($metric,['rating','botAccuracy'],true)?2:0,',','.')?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></details></section><?php endforeach;endif;?>
<section class="panel"><h3>Bankvermögen auf diesem Server</h3><?php if($economy['state']!=='ready'):?><p><?=Security::e($economy['message'])?></p><?php else:$last=null;$rank=0;?><p>Periode <?=$economy['data']['period']?> · <?=Security::e($economy['data']['generatedAt'])?></p><div class="table-wrap"><table><thead><tr><th>Platz</th><th>Spieler</th><th>Bank</th></tr></thead><tbody><?php foreach($economy['data']['rows'] as $i=>$r):if($last!==$r['balance'])$rank=$i+1;$last=$r['balance'];?><tr><td><?=$rank?></td><td><?=Security::e($r['name'])?> <small><?=Security::e($r['steamId'])?></small></td><td><?=number_format($r['balance'],0,',','.')?> $</td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php if($group):?><section class="panel"><h3><?=Security::e($group['name'])?></h3><p>Vorbereitet, noch nicht aktiviert. Guthaben werden nicht automatisch zusammengezählt. Eine Verbundrangliste wird erst nach geprüfter Übernahme aus dem gemeinsamen Kontenbestand gebildet.</p></section><?php endif;?>
